#Requires -Version 7.0
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$StoreReceipt,
    [Parameter(Mandatory)][string]$DesignationSha,
    [Parameter(Mandatory)][string]$InstallerReceipt,
    [Parameter(Mandatory)][string]$LedgerReceipt,
    [switch]$IssueAfterApproval
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
if (-not $IssueAfterApproval) { throw 'HOLD_ISSUANCE_NOT_APPROVED' }
$hostPath = 'C:\Program Files\PowerShell\7\pwsh.exe'
if (-not [Environment]::Is64BitProcess -or (Get-Process -Id $PID).Path -ine $hostPath) { throw 'HOLD_UNAPPROVED_HOST' }
$env:PSModulePath = Join-Path $PSHOME 'Modules'
Import-Module (Join-Path $PSHOME 'Modules\Microsoft.PowerShell.Security\Microsoft.PowerShell.Security.psd1')
$signature = Get-AuthenticodeSignature -LiteralPath $hostPath
if ($signature.Status -ne 'Valid' -or
    $signature.SignerCertificate.Subject -notmatch '(^|,\s*)O=Microsoft Corporation(,|$)') { throw 'HOLD_HOST_SIGNATURE' }

if ($StoreReceipt -cnotmatch '^[a-f0-9]{16}:[a-f0-9]{32}:[a-f0-9]{64}$' -or
    $DesignationSha -cnotmatch '^[a-f0-9]{64}$') { throw 'HOLD_APPROVAL_RECEIPT_FORMAT' }
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
try {
    $expectedSid = ([Security.Principal.NTAccount]::new([Environment]::MachineName, 'windows')).Translate([Security.Principal.SecurityIdentifier])
    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
    if (-not $expectedSid.Equals($identity.User) -or
        -not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'HOLD_SIGNER_TOKEN' }
    $sid = $identity.User.Value
} finally { $identity.Dispose() }
$embeddedAssembly = ''
$type = [Reflection.Assembly]::Load([Convert]::FromBase64String($embeddedAssembly)).GetType('LimitlessVerifierStorePreparation', $true)
try { $recordBytes = $type::ReadDesignation($sid, $StoreReceipt, $DesignationSha) }
catch {
    $cause = $_.Exception.GetBaseException()
    if ($cause -is [ComponentModel.Win32Exception]) { throw ("HOLD_RECORD_READ_{0}" -f $cause.NativeErrorCode) }
    if ($cause.Message -match '^HOLD_[A-Z_]+$') { throw $cause.Message }
    throw 'HOLD_RECORD_READ'
}
$utf8 = [Text.UTF8Encoding]::new($false, $true)
$record = $utf8.GetString($recordBytes) | ConvertFrom-Json -AsHashtable
$base = 'F:\study\codex\Project-Limitless\Temp\DiscordUsageDiagnostics20261026'
$candidate = Join-Path $base 'StagingVerifierRelease-3f674efb\candidate\Limitless.StagingVerifier.exe'
$checker = Join-Path $base 'Worktree\Tools\DiscordV2\StagingDraft\Test-ApprovedSigningKey.ps1'
$checkerSha = 'ab57366eef3eefe1e74c6f50cebf440c815d88e6ef8aada2ffa66c616448b24f'
if ($record.Schema -cne 'LIMITLESS_SIGNING_ACCOUNT_DESIGNATION_V1' -or
    $record.Approval -cne 'ISSUE66_SIGNER_DESIGNATION_RECORD_1' -or
    $record.Scope -cne 'ACCOUNT_DESIGNATION_ONLY' -or $record.Account -cne 'windows' -or
    $record.AccountSid -cne $sid -or $record.KeyCheckScriptPath -ine $checker -or
    $record.KeyCheckScriptSha256 -cne $checkerSha -or $record.CandidatePath -ine $candidate -or
    $record.CandidateSha256 -cne '145f3921e88ab2caba98afd4c5bb39eb7f9706aa6ad5e3fca5d5891f9f73adbb' -or
    $record.CertificateThumbprint -cne '437423567AD4B703578F231E34A06592B38DB4EB' -or
    $record.CertificateDerSha256 -cne '7dba5310d6ded0035595e5e7ab8b8b73422f2925b49c633426995c322940672c' -or
    $record.RsaSpkiSha256 -cne '2a6d0a7d31e7642df209b6cbe12fa628500663f540eb6bd557cac2aca2d31f7c') {
    throw 'HOLD_DESIGNATION_BINDING'
}

foreach ($receipt in @($InstallerReceipt,$LedgerReceipt)) {
    if ($receipt -cnotmatch '^[a-f0-9]{16}:[a-f0-9]{32}:[a-f0-9]{64}$') { throw 'HOLD_ISSUER_RECEIPT_FORMAT' }
}
$installerSha = '52694e574cee3068e0c84131dcd9b93d19a2b59a42a63cf322c87a596c91806d'
$sourceSha = 'caf59966f74e5d5d520a6a5245e9c118c75320ff138efe757d36619a058a37f7'
$sourceSigSha = '6892ef8aa4b5e85c20d5bd94e25e48e96d25dc116860ff2f0c9070bb74b0d388'
$installerName = 'Limitless.InitialStagingInstaller.exe'
$sourceName = 'StagingSource.ps1'
$sigName = 'StagingSource.sig'
$shaAlgorithm = [Security.Cryptography.HashAlgorithmName]::SHA256
$padding = [Security.Cryptography.RSASignaturePadding]::Pss
function ShaBytes([byte[]]$bytes) {
    [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)).ToLowerInvariant()
}

function Read-Checked([IO.Stream]$stream, [int]$limit, [string]$expected) {
    $stream.Position = 0
    if ($stream.Length -lt 1 -or $stream.Length -gt $limit) { throw 'HOLD_ISSUER_INPUT_SIZE' }
    $data = [byte[]]::new([int]$stream.Length)
    $stream.ReadExactly($data)
    if ((ShaBytes $data) -cne $expected) { throw 'HOLD_ISSUER_INPUT_SHA' }
    return ,$data
}

function Assert-IssuerCertificate($certificate) {
    $now = Get-Date
    $eku = @($certificate.Extensions |
        Where-Object { $_ -is [Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension] } |
        ForEach-Object EnhancedKeyUsages | ForEach-Object Value)
    if ($certificate.Thumbprint -cne $record.CertificateThumbprint -or
        $certificate.GetCertHashString($shaAlgorithm).ToLowerInvariant() -cne $record.CertificateDerSha256 -or
        $eku -notcontains '1.3.6.1.5.5.7.3.3' -or $now -lt $certificate.NotBefore -or $now -ge $certificate.NotAfter) {
        throw 'HOLD_ISSUER_CERTIFICATE'
    }
}
function Read-ApprovedSigner([string]$path) {
    $signature = Get-AuthenticodeSignature -LiteralPath $path
    if ($signature.Status -ne 'Valid' -or $null -eq $signature.SignerCertificate) { throw 'HOLD_ISSUER_AUTHENTICODE' }
    Assert-IssuerCertificate $signature.SignerCertificate
    return $signature.SignerCertificate
}

try {
    $storeType = $type.GetNestedType('InstallApprovalStore')
    $runtime = $storeType.GetField('RuntimePath').GetRawConstantValue()
    $ledger = $storeType.GetField('LedgerPath').GetRawConstantValue()
    $stage = $storeType.GetField('StagePath').GetRawConstantValue()
    $start = [DateTimeOffset]::UtcNow
    $store = [Activator]::CreateInstance($storeType, [object[]]@($sid,$start,$start.AddMinutes(5)))
    try {
        if ($store.LedgerReceipt -cne $LedgerReceipt) { throw 'HOLD_ISSUER_LEDGER_RECEIPT' }
        $store.CheckPreparation()
        $image = $store.Open($installerName)
        try {
            if ($store.Receipt($image,$installerName) -cne $InstallerReceipt) { throw 'HOLD_ISSUER_INSTALLER_RECEIPT' }
            $null = Read-Checked $image 67108864 $installerSha
            $null = Read-ApprovedSigner (Join-Path $runtime $installerName)
            $source = $store.Open($sourceName)
            try {
                $sourceSig = $store.Open($sigName)
                try {
                    $sourceBytes = Read-Checked $source 1048576 $sourceSha
                    $sourceSigBytes = Read-Checked $sourceSig 4096 $sourceSigSha
                    $leaf = Read-ApprovedSigner (Join-Path $runtime $sourceName)
                    $public = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($leaf)
                    if ($null -eq $public) { throw 'HOLD_ISSUER_PUBLIC_KEY' }
                    try {
                        if ((ShaBytes ($public.ExportSubjectPublicKeyInfo())) -cne $record.RsaSpkiSha256 -or
                            -not $public.VerifyData($sourceBytes,$sourceSigBytes,$shaAlgorithm,$padding)) {
                            throw 'HOLD_ISSUER_SOURCE_PSS'
                        }
                        $cert = Get-Item -LiteralPath "Cert:\LocalMachine\My\$($record.CertificateThumbprint)"
                        try {
                            Assert-IssuerCertificate $cert
                            $key = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPrivateKey($cert)
                            if ($null -eq $key) { throw 'HOLD_ISSUER_PRIVATE_KEY' }
                            try {
                                if ($key -isnot [Security.Cryptography.RSACng] -or
                                    $key.Key.ExportPolicy -ne [Security.Cryptography.CngExportPolicies]::None -or
                                    (ShaBytes ($key.ExportSubjectPublicKeyInfo())) -cne $record.RsaSpkiSha256) {
                                    throw 'HOLD_ISSUER_SIGNING_KEY'
                                }
                                $store.CheckPreparation()
                                $idNew = [guid]::NewGuid().ToString('N')
                                $store.CheckUnused($idNew)
                                $notBefore = [DateTimeOffset]::UtcNow
                                $expires = $notBefore.AddMinutes(5)
                                $rootParts = $store.RootReceipt.Split(':')
                                $parentParts = $store.ParentReceipt.Split(':')
                                $ledgerParts = $LedgerReceipt.Split(':')
                                $contract = [ordered]@{
                                    InstallerSha256 = $installerSha
                                    Approval = [ordered]@{
                                        Profile = 'DISCORD_V2_INITIAL_STAGING_INSTALL_V1'
                                        ApprovalId = $idNew
                                        Stage = $stage
                                        Ledger = $ledger
                                        LedgerKey = ($ledgerParts[0] + ':' + $ledgerParts[1])
                                        AdministratorSid = $sid
                                        NotBefore = $notBefore.UtcDateTime.ToString('o')
                                        Expires = $expires.UtcDateTime.ToString('o')
                                        SourceSha = $sourceSha
                                        ParentKeys = @(($rootParts[0] + ':' + $rootParts[1]),($parentParts[0] + ':' + $parentParts[1]))
                                        ParentSecurityHashes = @($rootParts[2],$parentParts[2])
                                    }
                                }
                                $plain = [Text.UTF8Encoding]::new($false).GetBytes(($contract | ConvertTo-Json -Depth 4 -Compress))
                                $signed = $key.SignData($plain,$shaAlgorithm,$padding)
                                if (-not $public.VerifyData($plain,$signed,$shaAlgorithm,$padding)) { throw 'HOLD_ISSUER_APPROVAL_PSS' }
                                $store.CheckPreparation()
                                $store.CheckUnused($idNew)
                                $sigReceipt = $store.WriteNew('InstallApproval.sig',$signed,$expires)
                                $jsonReceipt = $store.WriteNew('InstallApproval.json',$plain,$expires)
                                $copySig = $store.Open('InstallApproval.sig')
                                try {
                                    $copyJson = $store.Open('InstallApproval.json')
                                    try {
                                        $newSig = Read-Checked $copySig 4096 (ShaBytes $signed)
                                        $newJson = Read-Checked $copyJson 8192 (ShaBytes $plain)
                                        if ($store.Receipt($copySig,'InstallApproval.sig') -cne $sigReceipt -or
                                            $store.Receipt($copyJson,'InstallApproval.json') -cne $jsonReceipt -or
                                            -not $public.VerifyData($newJson,$newSig,$shaAlgorithm,$padding) -or
                                            [DateTimeOffset]::UtcNow -ge $expires) { throw 'HOLD_ISSUER_READBACK' }
                                        $store.CheckUnused($idNew)
                                        'INSTALL_APPROVAL_ISSUED_HANDLE_VERIFIED'
                                        "INSTALL_APPROVAL_SHA256=$(ShaBytes $newJson)"
                                        "INSTALL_APPROVAL_SIGNATURE_SHA256=$(ShaBytes $newSig)"
                                        "INSTALL_APPROVAL_EXPIRES_UTC=$($expires.UtcDateTime.ToString('o'))"
                                    } finally { $copyJson.Dispose() }
                                } finally { $copySig.Dispose() }
                            } finally { $key.Dispose() }
                        } finally { $cert.Dispose() }
                    } finally { $public.Dispose() }
                } finally { $sourceSig.Dispose() }
            } finally { $source.Dispose() }
        } finally { $image.Dispose() }
    } finally { $store.Dispose() }
} catch {
    $cause = $_.Exception.GetBaseException()
    if ($cause -is [ComponentModel.Win32Exception]) { throw ("HOLD_ISSUER_NATIVE_NO_RETRY_{0}" -f $cause.NativeErrorCode) }
    if ($cause.Message -match '^HOLD_[A-Z_]+$') { throw $cause.Message }
    throw 'HOLD_ISSUER_NO_RETRY'
}
